// Accept POST body shaped like { "prospects": [ {first_name, last_name, job_title, company_name, linkedin_url}, ... ] }
const body = $input.first().json.body || $input.first().json;
const list = Array.isArray(body) ? body : (body.prospects || []);
if (!Array.isArray(list) || list.length === 0) {
  throw new Error('No prospects provided. POST body must be {"prospects": [...]} or a JSON array.');
}
return list.map((p) => ({ json: p }));

// Country filter + priority sort.
// Priority (English-proficient, user-defined): MT, GB/UK, DE, FR, NL, SE, NO, DK, FI
// Secondary (other EU/EEA): AT BE BG HR CY CZ EE GR HU IS IE IT LV LI LT LU PL PT RO SK SI ES CH (Switzerland not EU/EEA but treat as secondary)
// Anything else: dropped.

const PRIORITY = new Set(['MT','MALTA','GB','UK','UNITED KINGDOM','GREAT BRITAIN','ENGLAND','SCOTLAND','WALES','NORTHERN IRELAND','DE','GERMANY','DEUTSCHLAND','FR','FRANCE','NL','NETHERLANDS','HOLLAND','SE','SWEDEN','NO','NORWAY','DK','DENMARK','FI','FINLAND']);

const SECONDARY = new Set(['AT','AUSTRIA','BE','BELGIUM','BG','BULGARIA','HR','CROATIA','CY','CYPRUS','CZ','CZECH REPUBLIC','CZECHIA','EE','ESTONIA','GR','GREECE','HU','HUNGARY','IS','ICELAND','IE','IRELAND','IT','ITALY','LV','LATVIA','LI','LIECHTENSTEIN','LT','LITHUANIA','LU','LUXEMBOURG','PL','POLAND','PT','PORTUGAL','RO','ROMANIA','SK','SLOVAKIA','SI','SLOVENIA','ES','SPAIN','CH','SWITZERLAND']);

const norm = (s) => String(s || '').trim().toUpperCase();

const tier = (c) => {
  const n = norm(c);
  if (!n) return 99;
  if (PRIORITY.has(n)) return 0;
  if (SECONDARY.has(n)) return 1;
  return 99;
};

const items = $input.all()
  .map((it) => ({ ...it, _tier: tier(it.json.country) }))
  .filter((it) => it._tier < 99)
  .sort((a, b) => a._tier - b._tier);

return items.map((it) => ({
  json: { ...it.json, country_tier: it._tier === 0 ? 'priority' : 'secondary' }
}));

const templates = [
  (p) => `Hi ${p.first_name}, came across your profile at ${p.company_name}. Would be great to connect.`,
  (p) => `Hi ${p.first_name}, I\u2019m connecting with founders and operators like yourself. Happy to connect here.`,
  (p) => `Hi ${p.first_name}, noticed your role at ${p.company_name}. Always open to connecting with people in leadership roles.`,
  (p) => `Hi ${p.first_name}, your work at ${p.company_name} caught my eye. Would love to connect.`
];

const item = $input.item.json;
const idx = Math.floor(Math.random() * templates.length);
const note = templates[idx](item).slice(0, 290);

return {
  json: {
    ...item,
    template_index: idx,
    connection_note: note
  }
};

const url = ($input.item.json.linkedin_url || '').trim();
const m = url.match(/linkedin\.com\/in\/([^\/\?#]+)/i);
if (!m) {
  throw new Error('Invalid linkedin_url: ' + url);
}
return { json: { ...$input.item.json, public_id: m[1] } };

const res = $input.item.json;
const code = res.statusCode || 0;
const ok = code >= 200 && code < 300;
const prospect = $('Extract Public ID').item.json;
return {
  json: {
    linkedin_url: prospect.linkedin_url,
    public_id: prospect.public_id,
    first_name: prospect.first_name || null,
    last_name: prospect.last_name || null,
    company_name: prospect.company_name || null,
    job_title: prospect.job_title || null,
    country: prospect.country || null,
    country_tier: prospect.country_tier || null,
    template_index: prospect.template_index,
    connection_note: prospect.connection_note,
    status: ok ? 'sent' : 'failed',
    http_status: code,
    reason: ok ? null : (JSON.stringify(res.body || {}).slice(0, 500))
  }
};

const min = parseInt($env.LINKEDIN_MIN_DELAY_SEC || '60', 10);
const max = parseInt($env.LINKEDIN_MAX_DELAY_SEC || '180', 10);
const seconds = Math.floor(Math.random() * (max - min + 1)) + min;
return { json: { delay_seconds: seconds } };
